pub fn namespace_root_from_properties(
    properties: Arc<Vec<Arc<Node>>>,
    name: String,
    source_indices: Arc<HashMap<String, Arc<NewlineIndex>>>,
) -> String {
    match Arc::new({
        let mut __result = Vec::new();
        for p in properties.clone().iter().cloned() {
            if (field_init_node_name_at(p.clone(), source_indices.clone())
                == "namespace_root".to_string())
            {
                __result.push(p);
            }
        }
        __result
    })
    .first()
    .cloned()
    {
        Some(ns_prop) => {
            match (*field_init_node_value(ns_prop.clone()).expr_data.clone()).clone() {
                ExprData::ExprLiteral { ref value, .. } => {
                    let LiteralValue::LitStr { value: root, .. } = value.as_ref() else {
                        unreachable!()
                    };
                    root.clone()
                }
                _ => name,
            }
        }
        None => name,
    }
}

