pub fn resolve_pattern_subject(
    scope: Arc<InferScope>,
    scrutinee_subject: Arc<PatternSubject>,
) -> Arc<PatternSubject> {
    match (*scrutinee_subject.clone()).clone() {
        PatternSubject::PatternResolved {
            node: scrutinee_type,
            ..
        } => pattern_subject_from_node(resolve_scrutinee_type_node(
            scope.type_env.clone(),
            scrutinee_type.clone(),
        )),
        PatternSubject::PatternDynamic {
            span: dynamic_span, ..
        } => Arc::new(PatternSubject::PatternDynamic {
            span: dynamic_span.clone(),
        }),
        PatternSubject::PatternLookupBlocked => Arc::new(PatternSubject::PatternLookupBlocked),
    }
}

pub fn annotate_pattern_parent_enums(
    pattern: Arc<MatchPattern>,
    scrutinee_subject: Arc<PatternSubject>,
    scope: Arc<InferScope>,
) -> Arc<MatchPattern> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*pattern.clone()).clone() {
            MatchPattern::VariantPattern {
                name: variant_name,
                field_bindings: bindings,
                ..
            } => {
                let resolved_scrut =
                    resolve_pattern_subject(scope.clone(), scrutinee_subject.clone());
                let inferred_parent = match (*resolved_scrut.clone()).clone() {
                    PatternSubject::PatternResolved {
                        node: resolved_scrut_node,
                        ..
                    } => {
                        let scrutinee_name = authored_name_at(
                            scope.type_env.clone().source_indices.clone(),
                            resolved_scrut_node.clone(),
                        );
                        let optional_cardinality_subject =
                            ((resolved_scrut_node.return_cardinality.clone()
                                == Cardinality::CardOptional)
                                && (scrutinee_name.clone() != "Optional".to_string()));
                        let optional_coproduct_subject = ((scrutinee_name.clone()
                            == "Optional".to_string())
                            && ((variant_name.clone() == "Present".to_string())
                                || (variant_name.clone() == "Absent".to_string())));
                        let witness_container_subject =
                            (is_witness_type_name(scrutinee_name.clone())
                                && ((variant_name.clone() == "Holds".to_string())
                                    || (variant_name.clone() == "Violates".to_string())));
                        if ((optional_cardinality_subject.clone()
                            || optional_coproduct_subject.clone())
                            && ((variant_name.clone() == "Present".to_string())
                                || (variant_name.clone() == "Absent".to_string())))
                        {
                            Some("Optional".to_string())
                        } else {
                            if witness_container_subject.clone() {
                                Some("Witness".to_string())
                            } else {
                                {
                                    let is_coproduct = (resolved_scrut_node.connective.clone()
                                        == Connective::Disj);
                                    if is_coproduct.clone() {
                                        Some(scrutinee_name.clone())
                                    } else {
                                        None
                                    }
                                }
                            }
                        }
                    }
                    PatternSubject::PatternDynamic { span: _, .. } => None,
                    PatternSubject::PatternLookupBlocked => None,
                };
                let annotated_variant_name = variant_name.clone();
                let variant_lookup = lookup_variant_in_type(
                    resolved_scrut.clone(),
                    variant_name.clone(),
                    scope.module_name.clone(),
                    scope.type_env.clone(),
                    (bindings.clone().len() as i64),
                );
                let variant_subject = lookup_result_subject(variant_lookup.clone());
                let annotated_bindings = Arc::new({
                    let mut __result = Vec::new();
                    for binding in bindings.clone().iter().cloned() {
                        __result.push({
                            let field_lookup = lookup_field_in_variant(
                                variant_subject.clone(),
                                field_binding_name_at(
                                    binding.clone(),
                                    scope.type_env.clone().source_indices.clone(),
                                ),
                                scope.module_name.clone(),
                                scope.type_env.clone().source_indices.clone(),
                            );
                            let field_subject = lookup_result_subject(field_lookup.clone());
                            make_field_binding_node(
                                field_binding_name_at(
                                    binding.clone(),
                                    scope.type_env.clone().source_indices.clone(),
                                ),
                                annotate_pattern_parent_enums(
                                    field_binding_pattern(binding.clone()),
                                    field_subject.clone(),
                                    scope.clone(),
                                ),
                                binding.span.clone(),
                                node_name_span(binding.clone()),
                            )
                        });
                    }
                    __result
                });
                match inferred_parent.clone() {
                    Some(parent_name) => Arc::new(MatchPattern::VariantPattern {
                        name: annotated_variant_name.clone(),
                        parent_enum: Some(parent_name.clone()),
                        field_bindings: annotated_bindings.clone(),
                    }),
                    None => Arc::new(MatchPattern::VariantPattern {
                        name: variant_name.clone(),
                        parent_enum: None,
                        field_bindings: annotated_bindings.clone(),
                    }),
                }
            }
            _ => pattern.clone(),
        }
    })
}

pub fn build_params_scope(scope: Arc<InferScope>, params: Arc<Vec<Arc<Node>>>) -> Arc<InferScope> {
    {
        let new_locals = params.clone().iter().cloned().fold(
            scope.locals.clone(),
            |acc: Arc<HashMap<String, Arc<TypeBinding>>>, p: Arc<Node>| {
                v1_rt::rc_map_insert(
                    acc,
                    param_node_name_at(p.clone(), scope.type_env.clone().source_indices.clone()),
                    Arc::new(TypeBinding {
                        name: param_node_name_at(
                            p.clone(),
                            scope.type_env.clone().source_indices.clone(),
                        ),
                        resolved: param_node_type_expr(p.clone()),
                        provenance: Arc::new(SubValueRelation::PreservedValue),
                    }),
                )
            },
        );
        let new_body_locals = params.clone().iter().cloned().fold(
            scope.body_locals.clone(),
            |acc: Arc<HashMap<String, bool>>, p: Arc<Node>| {
                v1_rt::rc_map_insert(
                    acc,
                    param_node_name_at(p.clone(), scope.type_env.clone().source_indices.clone()),
                    true,
                )
            },
        );
        Arc::new(InferScope {
            type_env: scope.type_env.clone(),
            func_env: scope.func_env.clone(),
            locals: new_locals.clone(),
            body_locals: new_body_locals.clone(),
            match_bound_names: scope.match_bound_names.clone(),
            module_name: scope.module_name.clone(),
            service_registry: scope.service_registry.clone(),
            item_registry: scope.item_registry.clone(),
            lambda_param_provenance: v1_rt::rc_empty_map::<String, Arc<SubValueRelation>>(),
        })
    }
}

